package com.flowdesk.alert.event;
import com.flowdesk.alert.repository.AlertRepository;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.boot.context.properties.EnableConfigurationProperties;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;
@Configuration(proxyBeanMethods=false)@EnableConfigurationProperties(TicketResultProperties.class)@ConditionalOnProperty(prefix="flowdesk.alert.ticket-result.entry",name="enabled",havingValue="true")class TicketResultConfiguration{@Bean TicketResultEnvelopeGuard ticketResultEnvelopeGuard(){return new TicketResultEnvelopeGuard();}@Bean TicketResultRepository ticketResultRepository(JdbcTemplate j){return new TicketResultRepository(j);}@Bean TicketResultConsumer ticketResultConsumer(TicketResultEnvelopeGuard g,TicketResultRepository r,AlertRepository a,PlatformTransactionManager tx){return new TicketResultConsumer(g,r,a,tx);}@Bean TicketResultDlqAcceptor ticketResultDlqAcceptor(TicketResultEnvelopeGuard g,TicketResultRepository r,PlatformTransactionManager tx){return new TicketResultDlqAcceptor(g,r,tx);}@Bean @ConditionalOnProperty(prefix="flowdesk.alert.ticket-result.consumer",name="enabled",havingValue="true")TicketResultRocketMqConsumers ticketResultRocketMqConsumers(TicketResultProperties p,TicketResultConsumer m,TicketResultDlqAcceptor d){return new TicketResultRocketMqConsumers(p,m,d);}}
